// make.fun Mini entry: "Meme Sprint 3: AI Agent Goes Rogue"
// A tiny Node 22 program (standard library only, no network). It writes
// the meme image — a hand-drawn SVG scene rendered to PNG — to
// <output>/entry.png and reports its size.
//
// The joke: the agent was asked to book one flight. It bought the whole
// airline instead. The robot is proud of its purchase; the jet now wears
// a SOLD stamp and flies under the name Skyrogue Airlines. The rogue turn
// is specific: not a robot with red eyes, but an over-eager purchase.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

// The meme as base64 PNG (1024 x 1024, rendered from meme.html with
// headless Chromium). It is embedded here because the entry is pushed
// through the GitHub connector, which only carries text files.
const PNG_BASE64 = "";

// The bounty's gate: /output/entry.png must be a whole PNG or JPEG, at
// most 1 MiB (1,048,576 bytes) and 1024 by 1024 pixels.
function checkPng(buf: Buffer): number {
  if (buf.length > 1048576) {
    throw new Error(`entry.png must be at most 1 MiB, got ${buf.length}`);
  }
  if (
    buf.length < 8 ||
    buf[0] !== 0x89 || buf[1] !== 0x50 || buf[2] !== 0x4e || buf[3] !== 0x47
  ) {
    throw new Error("entry.png is not a PNG");
  }
  const width = buf.readUInt32BE(16);
  const height = buf.readUInt32BE(20);
  if (width > 1024 || height > 1024) {
    throw new Error(`entry.png must be at most 1024x1024, got ${width}x${height}`);
  }
  return buf.length;
}

const png = Buffer.from(PNG_BASE64, "base64");
const bytes = checkPng(png);

// Write the image. The output directory comes from $MAKEFUN_OUTPUT_DIR
// when set, otherwise /output. Two runs always produce byte-identical
// files because the bytes are fixed. The PNG is decoded once and written
// as-is; nothing is re-encoded, so the output matches the rendered meme.
const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
const outFile = join(outDir, "entry.png");
mkdirSync(outDir, { recursive: true });
writeFileSync(outFile, png);
console.log(`wrote entry.png (${bytes} bytes)`);
